import{b as i,O as a,g as t,j as e}from"./chunks/framework.DcaUmd3X.js";const c=JSON.parse('{"title":"撤销与删除","description":"","frontmatter":{},"headers":[],"relativePath":"git/basics/restore/index.md","filePath":"Git操作手册/2.基础操作/05.撤销与删除.md","lastUpdated":1782199931000}'),h={name:"git/basics/restore/index.md"};function n(l,s,d,p,o,k){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="撤销与删除" tabindex="-1">撤销与删除 <a class="header-anchor" href="#撤销与删除" aria-label="Permalink to &quot;撤销与删除&quot;">​</a></h1><blockquote><p>git rm / git mv / 文件删错了怎么找回来</p></blockquote><h2 id="删除文件要分两步" tabindex="-1">删除文件要分两步 <a class="header-anchor" href="#删除文件要分两步" aria-label="Permalink to &quot;删除文件要分两步&quot;">​</a></h2><p>在 Git 管理的仓库里删文件，和普通删文件不一样。普通 <code>rm</code> 只删了工作区的文件，Git 还不知道这件事：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> old-file.js</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># deleted:    old-file.js   ← Git 检测到文件没了，但这个删除还没进暂存区</span></span></code></pre></div><p>要两步才算完整删除：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> old-file.js</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 第一步：删掉文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> old-file.js</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 第二步：告诉 Git &quot;这个删除操作我要提交&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;删除不再使用的 old-file.js&quot;</span></span></code></pre></div><h2 id="一条命令搞定-git-rm" tabindex="-1">一条命令搞定：git rm <a class="header-anchor" href="#一条命令搞定-git-rm" aria-label="Permalink to &quot;一条命令搞定：git rm&quot;">​</a></h2><p>不想分两步？用 <code>git rm</code>，一步删除文件并把删除操作加入暂存区：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> old-file.js</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;删除 old-file.js&quot;</span></span></code></pre></div><p>等价于 <code>rm 文件</code> + <code>git add 文件</code>。</p><h3 id="只让-git-忘记-不删文件本身" tabindex="-1">只让 Git 忘记，不删文件本身 <a class="header-anchor" href="#只让-git-忘记-不删文件本身" aria-label="Permalink to &quot;只让 Git 忘记，不删文件本身&quot;">​</a></h3><p>比如你之前把 <code>secret.config</code> 提交到了仓库，后来发现这个文件里有机密信息，不应该被 Git 跟踪。你想让它从 Git 的跟踪列表里消失，但文件本身还要留在本地用：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cached</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret.config</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;secret.config&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .gitignore</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 加入忽略列表，防止再次提交</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;从 git 中移除 secret.config&quot;</span></span></code></pre></div><p>文件还在你的目录里，但 Git 不再跟踪它了。之后修改这个文件，<code>git status</code> 也不会显示。</p><h2 id="文件被误删了怎么找回" tabindex="-1">文件被误删了怎么找回 <a class="header-anchor" href="#文件被误删了怎么找回" aria-label="Permalink to &quot;文件被误删了怎么找回&quot;">​</a></h2><p>不管你是用 <code>rm</code> 删的还是手滑在 IDE 里删的——只要文件曾经 <code>commit</code> 过，Git 就能找回来：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 从最新提交中恢复</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 被删的文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 从指定提交中恢复</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --source=commit_id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 被删的文件</span></span></code></pre></div><h2 id="重命名-移动文件" tabindex="-1">重命名 / 移动文件 <a class="header-anchor" href="#重命名-移动文件" aria-label="Permalink to &quot;重命名 / 移动文件&quot;">​</a></h2><p>给文件改名，用 <code>git mv</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> old-name.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new-name.js</span></span></code></pre></div><p>这等同于是先 <code>mv</code> 再 <code>git add</code> 两步的组合——Git 会自动识别这是重命名，不会当成&quot;删了一个文件 + 新建一个文件&quot;。提交后历史是连续的。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>命令</th><th>说明</th></tr></thead><tbody><tr><td>删除并暂存</td><td><code>git rm 文件</code></td><td>一步等于 rm + add</td></tr><tr><td>停止跟踪但不删文件</td><td><code>git rm --cached 文件</code></td><td>文件保留，Git 不再管</td></tr><tr><td>重命名</td><td><code>git mv 旧名 新名</code></td><td>Git 自动识别为改名</td></tr><tr><td>找回误删的文件</td><td><code>git restore 文件</code></td><td>前提：之前 commit 过</td></tr></tbody></table><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>新建一个文件、commit，然后用 <code>git rm</code> 删除它，提交后再用 <code>git restore</code> 从历史中找回来</li><li>创建一个配置文件，用 <code>git rm --cached</code> 让 Git 停止跟踪，确认文件还在目录里</li><li>用 <code>git mv</code> 给一个文件改名，再 <code>git log --oneline</code> 确认历史是连续的</li></ol>`,26)])])}const g=i(h,[["render",n]]);export{c as __pageData,g as default};
